insert into public.app_permissions(permission_code,module,description,risk_level,active)
values
 ('ORCHESTRATION_VIEW','ORCHESTRATION','Ver orquestación, resiliencia y escenarios','NORMAL',true),
 ('ORCHESTRATION_WRITE','ORCHESTRATION','Gestionar escenarios y decisiones de orquestación','SENSIBLE',true)
on conflict(permission_code) do update set module=excluded.module,description=excluded.description,risk_level=excluded.risk_level,active=true;

insert into public.role_permissions(role_id,permission_code)
select distinct rp.role_id,'ORCHESTRATION_VIEW' from public.role_permissions rp where rp.permission_code in ('PREDICTIVE_VIEW','MANAGEMENT_REVIEW_VIEW') on conflict do nothing;
insert into public.role_permissions(role_id,permission_code)
select distinct rp.role_id,'ORCHESTRATION_WRITE' from public.role_permissions rp where rp.permission_code='PREDICTIVE_WRITE' on conflict do nothing;

create table if not exists public.orchestration_scenarios(
 id uuid primary key default gen_random_uuid(), scenario_code text not null unique, branch_id uuid null references public.branches(id), name text not null,
 horizon_days integer not null default 30 check(horizon_days in (7,14,30,60,90)), demand_multiplier numeric(8,3) not null default 1 check(demand_multiplier between 0.1 and 5), donor_multiplier numeric(8,3) not null default 1 check(donor_multiplier between 0.1 and 5), collection_multiplier numeric(8,3) not null default 1 check(collection_multiplier between 0.1 and 5), capacity_multiplier numeric(8,3) not null default 1 check(capacity_multiplier between 0.1 and 5), loss_reduction_pct numeric(6,2) not null default 0 check(loss_reduction_pct between 0 and 100), assumptions text, status text not null default 'BORRADOR' check(status in ('BORRADOR','REVISADO','APROBADO','ARCHIVADO')), created_by uuid not null default auth.uid(), created_at timestamptz not null default now(), reviewed_by uuid, reviewed_at timestamptz, updated_at timestamptz not null default now()
);
alter table public.orchestration_scenarios enable row level security;
revoke all on public.orchestration_scenarios from anon;
grant select,insert,update,delete on public.orchestration_scenarios to authenticated;
create policy orchestration_scenarios_select on public.orchestration_scenarios for select to authenticated using (has_permission('ORCHESTRATION_VIEW') and (branch_id is null or can_access_branch(branch_id)));
create policy orchestration_scenarios_insert on public.orchestration_scenarios for insert to authenticated with check (has_permission('ORCHESTRATION_WRITE') and (branch_id is null or can_access_branch(branch_id)) and created_by=(select auth.uid()));
create policy orchestration_scenarios_update on public.orchestration_scenarios for update to authenticated using (has_permission('ORCHESTRATION_WRITE') and (branch_id is null or can_access_branch(branch_id))) with check (has_permission('ORCHESTRATION_WRITE') and (branch_id is null or can_access_branch(branch_id)));
create policy orchestration_scenarios_delete on public.orchestration_scenarios for delete to authenticated using (has_permission('ORCHESTRATION_WRITE') and (branch_id is null or can_access_branch(branch_id)));
create index if not exists idx_orchestration_scenarios_branch_status on public.orchestration_scenarios(branch_id,status);
create index if not exists idx_orchestration_scenarios_created_by on public.orchestration_scenarios(created_by);

create or replace view public.vw_branch_resilience_score with (security_invoker=true) as
select b.id branch_id,b.name branch_name,coalesce(sr.critical_stock,0) critical_stock,coalesce(sr.high_stock,0) high_stock,coalesce(pa.critical_actions,0) critical_actions,coalesce(pa.overdue_actions,0) overdue_actions,coalesce(al.loss_value,0)::numeric loss_value_30d,coalesce(ch.at_risk_customers,0) at_risk_customers,
greatest(0,100-least(100,coalesce(sr.critical_stock,0)*18+coalesce(sr.high_stock,0)*8+coalesce(pa.critical_actions,0)*8+coalesce(pa.overdue_actions,0)*5+coalesce(ch.at_risk_customers,0)*4+case when coalesce(al.loss_value,0)>0 then 8 else 0 end))::integer resilience_score,
case when greatest(0,100-least(100,coalesce(sr.critical_stock,0)*18+coalesce(sr.high_stock,0)*8+coalesce(pa.critical_actions,0)*8+coalesce(pa.overdue_actions,0)*5+coalesce(ch.at_risk_customers,0)*4+case when coalesce(al.loss_value,0)>0 then 8 else 0 end))<50 then 'CRITICA' when greatest(0,100-least(100,coalesce(sr.critical_stock,0)*18+coalesce(sr.high_stock,0)*8+coalesce(pa.critical_actions,0)*8+coalesce(pa.overdue_actions,0)*5+coalesce(ch.at_risk_customers,0)*4+case when coalesce(al.loss_value,0)>0 then 8 else 0 end))<70 then 'ALTA' when greatest(0,100-least(100,coalesce(sr.critical_stock,0)*18+coalesce(sr.high_stock,0)*8+coalesce(pa.critical_actions,0)*8+coalesce(pa.overdue_actions,0)*5+coalesce(ch.at_risk_customers,0)*4+case when coalesce(al.loss_value,0)>0 then 8 else 0 end))<85 then 'MEDIA' else 'CONTROLADA' end resilience_risk
from public.branches b
left join (select branch_id,count(*) filter(where risk_level='CRITICO')::int critical_stock,count(*) filter(where risk_level='ALTO')::int high_stock from public.vw_stock_risk_projection group by branch_id) sr on sr.branch_id=b.id
left join (select branch_id,count(*) filter(where priority='CRITICA')::int critical_actions,count(*) filter(where due_date<current_date)::int overdue_actions from public.vw_predictive_action_queue group by branch_id) pa on pa.branch_id=b.id
left join (select branch_id,sum(loss_value) loss_value from public.vw_avoidable_loss_signals where avoidable is true group by branch_id) al on al.branch_id=b.id
left join (select branch_id,count(*) filter(where health_score<60)::int at_risk_customers from public.vw_customer_health_score group by branch_id) ch on ch.branch_id=b.id
where can_access_branch(b.id);
grant select on public.vw_branch_resilience_score to authenticated; revoke all on public.vw_branch_resilience_score from anon;

create or replace view public.vw_supplier_risk_score with (security_invoker=true) as
select id supplier_id,supplier_code,legal_name,critical,status,evaluation_date,total_score,result,next_review_date,review_overdue,greatest(0,least(100,100-(case when critical then 15 else 0 end)-(case when review_overdue then 25 else 0 end)-greatest(0,70-coalesce(total_score,0))))::integer supplier_health_score,case when review_overdue and critical then 'CRITICO' when coalesce(total_score,0)<50 then 'ALTO' when coalesce(total_score,0)<70 or review_overdue then 'MEDIO' else 'CONTROLADO' end supplier_risk from public.vw_supplier_performance;
grant select on public.vw_supplier_risk_score to authenticated; revoke all on public.vw_supplier_risk_score from anon;

create or replace view public.vw_donor_campaign_efficiency with (security_invoker=true) as
select d.id campaign_id,d.campaign_code,d.branch_id,d.name,d.channel,d.status,d.target_donors,p.donations_captured,p.attainment_pct,d.contacts_reached,d.planned_cost,d.actual_cost,case when coalesce(d.contacts_reached,0)>0 then round((p.donations_captured::numeric/nullif(d.contacts_reached,0))*100,2) end contact_to_donation_pct,case when p.donations_captured>0 then round(coalesce(d.actual_cost,d.planned_cost,0)/p.donations_captured,2) end cost_per_donation,case when coalesce(d.actual_cost,d.planned_cost,0)>0 then round(p.donations_captured/coalesce(d.actual_cost,d.planned_cost,0)*1000,2) end donations_per_1000_cost from public.donor_campaigns d join public.vw_donor_campaign_performance p on p.id=d.id;
grant select on public.vw_donor_campaign_efficiency to authenticated; revoke all on public.vw_donor_campaign_efficiency from anon;

create or replace view public.vw_data_quality_readiness with (security_invoker=true) as
select b.id branch_id,b.name branch_name,(select count(*) from public.operational_sales s where s.branch_id=b.id and s.customer_id is null)::int sales_without_customer,(select count(*) from public.operational_sales s where s.branch_id=b.id and s.demand_request_id is null)::int sales_without_demand,(select count(*) from public.dispatches d where d.branch_id=b.id and d.demand_request_id is null)::int dispatches_without_demand,(select count(*) from public.donations d where d.branch_id=b.id and d.campaign_id is null and d.created_at>=now()-interval '30 days')::int recent_donations_without_campaign,greatest(0,100-least(100,(select count(*) from public.operational_sales s where s.branch_id=b.id and s.customer_id is null)*5+(select count(*) from public.dispatches d where d.branch_id=b.id and d.demand_request_id is null)*3+(select count(*) from public.operational_sales s where s.branch_id=b.id and s.demand_request_id is null)*3))::integer data_readiness_score from public.branches b where can_access_branch(b.id);
grant select on public.vw_data_quality_readiness to authenticated; revoke all on public.vw_data_quality_readiness from anon;

create or replace view public.vw_scenario_impact with (security_invoker=true) as
select s.id scenario_id,s.scenario_code,s.branch_id,b.name branch_name,s.name,s.horizon_days,s.status,s.demand_multiplier,s.donor_multiplier,s.collection_multiplier,s.capacity_multiplier,s.loss_reduction_pct,coalesce(p.revenue,0) baseline_revenue_30d,round(coalesce(p.revenue,0)*s.demand_multiplier*s.capacity_multiplier,2) projected_revenue,coalesce(p.donations_count,0) baseline_donations_30d,round(coalesce(p.donations_count,0)*s.donor_multiplier,2) projected_donations,coalesce(cf.expected_cash,0) baseline_expected_cash,round(coalesce(cf.expected_cash,0)*s.collection_multiplier,2) projected_cash,coalesce(p.loss,0) baseline_loss_30d,round(coalesce(p.loss,0)*(1-s.loss_reduction_pct/100.0),2) projected_loss,round(coalesce(p.net_value_proxy,0)*s.demand_multiplier*s.capacity_multiplier+coalesce(cf.expected_cash,0)*(s.collection_multiplier-1)+coalesce(p.loss,0)*(s.loss_reduction_pct/100.0),2) projected_value_proxy from public.orchestration_scenarios s left join public.branches b on b.id=s.branch_id left join public.vw_branch_productivity_30d p on p.branch_id=s.branch_id left join (select branch_id,sum(expected_cash) expected_cash from public.vw_cash_collection_forecast where forecast_week<=current_date+60 group by branch_id) cf on cf.branch_id=s.branch_id;
grant select on public.vw_scenario_impact to authenticated; revoke all on public.vw_scenario_impact from anon;

create or replace view public.vw_orchestration_priority_queue with (security_invoker=true) as
select 'PREDICTIVE:'||candidate_key priority_key,branch_id,domain,priority,title,description,due_date,recommended_action from public.vw_predictive_action_queue
union all select 'RESILIENCE:'||branch_id::text,branch_id,'RESILIENCIA',case when resilience_risk='CRITICA' then 'CRITICA' when resilience_risk='ALTA' then 'ALTA' else 'MEDIA' end,'Resiliencia de sucursal '||resilience_risk,'Score de resiliencia: '||resilience_score::text,current_date+7,'Revisar stock, acciones vencidas, clientes en riesgo y pérdidas evitables' from public.vw_branch_resilience_score where resilience_score<85
union all select 'SUPPLIER:'||supplier_id::text,null::uuid,'PROVEEDOR',case when supplier_risk='CRITICO' then 'CRITICA' when supplier_risk='ALTO' then 'ALTA' else 'MEDIA' end,'Riesgo de proveedor: '||legal_name,'Score proveedor: '||supplier_health_score::text,next_review_date,'Revisar evaluación, continuidad y proveedor alterno' from public.vw_supplier_risk_score where supplier_risk<>'CONTROLADO';
grant select on public.vw_orchestration_priority_queue to authenticated; revoke all on public.vw_orchestration_priority_queue from anon;

create or replace view public.vw_management_review_pack_v2 with (security_invoker=true) as
select b.id branch_id,b.name branch_name,r.resilience_score,r.resilience_risk,d.data_readiness_score,coalesce((select count(*) from public.vw_orchestration_priority_queue q where q.branch_id=b.id),0)::int priority_items,coalesce((select count(*) from public.integrated_actions a where a.branch_id=b.id and a.status not in ('CERRADA','CANCELADA')),0)::int open_integrated_actions,coalesce((select count(*) from public.orchestration_scenarios s where s.branch_id=b.id and s.status in ('BORRADOR','REVISADO')),0)::int active_scenarios,coalesce((select sum(balance) from public.vw_customer_health_score c where c.branch_id=b.id),0)::numeric receivable_balance,coalesce((select sum(loss_value) from public.vw_avoidable_loss_signals l where l.branch_id=b.id and l.avoidable is true),0)::numeric avoidable_loss_value from public.branches b left join public.vw_branch_resilience_score r on r.branch_id=b.id left join public.vw_data_quality_readiness d on d.branch_id=b.id where can_access_branch(b.id);
grant select on public.vw_management_review_pack_v2 to authenticated; revoke all on public.vw_management_review_pack_v2 from anon;
